tasks.register<Exec>("convertMavenProject") {
    val workDir = layout.buildDirectory.dir("pom-convert").get().asFile
    group = "development"
    // Provide a brief description of what the task does
    description = "Converts pom.xml into a build.gradle.kts file using `gradle init`"
    
        workDir.mkdirs()
        project.copy {
            from("pom.xml")
            into(workDir)
        }
    
    workingDir(workDir)
    commandLine("gradle", "init", "--type", "pom", "--dsl", "kotlin", "--no-comments")
        project.copy {
            from(File(workDir, "build.gradle"))
            into(layout.projectDirectory)
            rename { "build.gradle.converted" }
        }
}

publishing {
    publications {
        create<MavenPublication>("maven") {
            from(components["java"])
        }
    }
}

abstract class DecompileDependenciesTask @Inject constructor(
    private val execOperations: ExecOperations,
) : DefaultTask() {

    @get:InputFiles
    abstract val dependencyJars: ConfigurableFileCollection

    @get:OutputDirectory
    abstract val outputDirectory: DirectoryProperty

    @TaskAction
    fun decompile() {
        val vineflowerJar = File(System.getProperty("user.home"), ".local/bin/vineflower.jar")

        if (!vineflowerJar.isFile) {
            val installerUrl =
                "https://gist.githubusercontent.com/nokernelspace/e8b84528dd255fc419c6076e21c6b299/raw/5a932f127f4152cfae96a491253d8de89d9fb9b4/install_vineflower.sh"
            val installer = File(temporaryDir, "install_vineflower.sh")
            installer.writeText(URI.create(installerUrl).toURL().readText())
            installer.setExecutable(true)
            execOperations.exec {
                commandLine("bash", installer.absolutePath)
            }
        }

        val outputRoot = outputDirectory.get().asFile
        outputRoot.mkdirs()

        dependencyJars.files.forEach { dependency ->
            val target = File(outputRoot, dependency.nameWithoutExtension)
            logger.lifecycle("Decompiling ${dependency.name} -> $target")
            execOperations.exec {
                commandLine(
                    "java", "-jar", vineflowerJar.absolutePath,
                    dependency.absolutePath, target.absolutePath,
                )
            }
        }
    }
}

tasks.register<DecompileDependenciesTask>("decompileDependencies") {
    group = "development"
    description = "Decompile Gradle Dependencies using ~/.local/bin/vineflower.jar"
    dependencyJars.from(configurations.named("runtimeClasspath"))
    outputDirectory.set(layout.buildDirectory.dir("decompiled"))
}
